<path data-kind="relationship" data-object-id="r1" data-status="unchanged" data-signature="https:create" data-from="storefront" data-to="api" d="M 168 64 V 96" fill="none" stroke="#bfc0c0" stroke-width="1.2" marker-end="url(#architecture-delta-dark-arrow)"/>
