      <text x="400" y="370" fill="#4f5d75" font-size="9" font-family="'Geist Mono', monospace" text-anchor="middle">packages/shared-types</text>

      <!-- db -->
      <rect x="520" y="320" width="160" height="56" rx="6" fill="#f5f5f5"/>
